// A tiny zero-dependency book tracker.
// Stores books in books.json so they survive restarts. No accounts, no database.
//
//   node server.mjs            # serves on http://localhost:3000
//   PORT=4000 node server.mjs   # pick a port

import { createServer } from 'node:http';
import { randomUUID } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const PORT = Number(process.env.PORT) || 3000;
const DATA_FILE = join(process.cwd(), 'books.json');

const __dirname = dirname(fileURLToPath(import.meta.url));

// ---------- storage ----------

/** @typedef {{ id: string, title: string, author: string, notes: string, finished: boolean, addedAt: string }} Book */

function loadBooks() {
  if (!existsSync(DATA_FILE)) return [];
  try {
    const raw = readFileSync(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch (err) {
    console.error(`Could not parse ${DATA_FILE}, starting empty: ${err.message}`);
    return [];
  }
}

function saveBooks(books) {
  writeFileSync(DATA_FILE, JSON.stringify(books, null, 2));
}

function findBook(books, id) {
  return books.find((b) => b.id === id);
}

// ---------- request helpers ----------

function readBody(req) {
  return new Promise((resolve) => {
    let body = '';
    req.on('data', (chunk) => (body += chunk));
    req.on('end', () => resolve(body));
    req.on('error', () => resolve(''));
  });
}

function formDecode(body) {
  const params = new URLSearchParams(body);
  const out = {};
  for (const [key, value] of params.entries()) {
    out[key] = value.trim();
  }
  return out;
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function escapeAttr(value) {
  return escapeHtml(value);
}

// Multi-line notes -> safe HTML with line breaks preserved.
function notesToHtml(notes) {
  return escapeHtml(notes).replace(/\r?\n/g, '<br>');
}

// ---------- views ----------

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light dark; }
    body {
      font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      max-width: 680px; margin: 2rem auto; padding: 0 1rem;
      background: #fafafa; color: #222;
    }
    h1 { font-size: 1.5rem; margin: 0 0 1rem; }
    h2 { font-size: 1.15rem; margin: 1.75rem 0 0.75rem; color: #555; }
    a { color: #1a5fb4; }
    .book { background: #fff; border: 1px solid #e3e3e3; border-radius: 8px;
            padding: 0.85rem 1rem; margin: 0.5rem 0; display: flex; gap: 0.75rem;
            align-items: center; justify-content: space-between; }
    .book .meta { min-width: 0; }
    .book .title { font-weight: 600; }
    .book .author { color: #666; font-size: 0.9rem; }
    .actions { display: flex; gap: 0.5rem; flex-shrink: 0; }
    button, .btn { font: inherit; cursor: pointer; border: 1px solid #ccc;
            background: #fff; color: #222; border-radius: 6px; padding: 0.3rem 0.7rem;
            text-decoration: none; }
    button:hover, .btn:hover { background: #f0f0f0; }
    button.primary { background: #1a5fb4; color: #fff; border-color: #1a5fb4; }
    button.primary:hover { background: #174f95; }
    form.inline { display: inline; }
    .empty { color: #888; font-style: italic; padding: 0.5rem 0; }
    form.card { background: #fff; border: 1px solid #e3e3e3; border-radius: 8px;
            padding: 1rem; margin: 1rem 0; }
    label { display: block; font-weight: 600; margin: 0.5rem 0 0.25rem; }
    input, textarea { width: 100%; box-sizing: border-box; font: inherit;
            padding: 0.4rem 0.5rem; border: 1px solid #ccc; border-radius: 6px; }
    textarea { min-height: 5rem; resize: vertical; }
    .share-link { background: #f0f4f9; border: 1px dashed #b9c8da; border-radius: 6px;
            padding: 0.6rem 0.75rem; word-break: break-all; font-family: ui-monospace, monospace; font-size: 0.85rem; }
    .back { margin-bottom: 1rem; display: inline-block; }
    .badge { font-size: 0.75rem; background: #e6f4ea; color: #1e7e34; border-radius: 999px;
            padding: 0.1rem 0.5rem; }
  </style>
</head>
<body>
${body}
</body>
</html>`;
}

function homeView(books, origin) {
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  const renderItem = (b) => `
    <li class="book">
      <div class="meta">
        <div><a class="title" href="/books/${escapeAttr(b.id)}">${escapeHtml(b.title)}</a></div>
        <div class="author">${escapeHtml(b.author || 'Unknown author')}</div>
      </div>
      <div class="actions">
        ${b.finished
          ? ''
          : `<form class="inline" method="post" action="/books/${escapeAttr(b.id)}/finish">
               <button type="submit">Mark finished</button>
             </form>`}
        <a class="btn" href="/books/${escapeAttr(b.id)}">Open</a>
      </div>
    </li>`;

  const readingList = reading.length
    ? `<ul style="list-style:none;padding:0">${reading.map(renderItem).join('')}</ul>`
    : `<p class="empty">Nothing in progress yet. Add a book below.</p>`;

  const finishedList = finished.length
    ? `<ul style="list-style:none;padding:0">${finished.map(renderItem).join('')}</ul>`
    : `<p class="empty">No finished books yet.</p>`;

  const form = `
    <form class="card" method="post" action="/books">
      <h2 style="margin-top:0">Add a book</h2>
      <label for="title">Title</label>
      <input id="title" name="title" required placeholder="The Pragmatic Programmer">
      <label for="author">Author</label>
      <input id="author" name="author" placeholder="Andy Hunt & Dave Thomas">
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" placeholder="What's it about? Why are you reading it?"></textarea>
      <div style="margin-top:0.75rem">
        <button class="primary" type="submit">Add to currently reading</button>
      </div>
    </form>`;

  const body = `
    <h1>📚 Book tracker</h1>

    <h2>Currently reading</h2>
    ${readingList}

    <h2>Finished</h2>
    ${finishedList}

    ${form}
  `;
  return page('Book tracker', body);
}

function bookView(book, origin) {
  const shareUrl = `${origin}/books/${book.id}`;
  const body = `
    <a class="back" href="/">&larr; All books</a>
    <h1>${escapeHtml(book.title)}</h1>
    <p class="author" style="color:#666;margin-top:-0.5rem">by ${escapeHtml(book.author || 'Unknown author')}</p>
    <p>${book.finished ? '<span class="badge">Finished</span>' : '<span class="badge" style="background:#fff4e6;color:#9a6a00">Currently reading</span>'}</p>

    <h2>Notes</h2>
    ${book.notes ? `<div>${notesToHtml(book.notes)}</div>` : `<p class="empty">No notes yet.</p>`}

    <h2>Share link</h2>
    <div class="share-link">${escapeHtml(shareUrl)}</div>

    <div class="actions" style="margin-top:1.25rem">
      ${book.finished ? '' : `<form class="inline" method="post" action="/books/${escapeAttr(book.id)}/finish">
        <button class="primary" type="submit">Mark finished</button>
      </form>`}
      <a class="btn" href="/">All books</a>
    </div>
  `;
  return page(book.title, body);
}

function notFoundView() {
  return page('Not found', `
    <h1>Not found</h1>
    <p>That book doesn't exist.</p>
    <a class="btn" href="/">Back to all books</a>
  `);
}

// ---------- routing ----------

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;
  const origin = `${url.protocol}//${url.host}`;

  try {
    // POST /books  -> create
    if (req.method === 'POST' && path === '/books') {
      const fields = formDecode(await readBody(req));
      const title = fields.title || '';
      if (!title) {
        res.statusCode = 400;
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.end(page('Error', `<h1>Title is required</h1><a class="btn" href="/">Back</a>`));
      }
      const books = loadBooks();
      /** @type {Book} */
      const book = {
        id: randomUUID(),
        title,
        author: fields.author || '',
        notes: fields.notes || '',
        finished: false,
        addedAt: new Date().toISOString(),
      };
      books.push(book);
      saveBooks(books);
      res.statusCode = 303;
      res.setHeader('Location', `/books/${book.id}`);
      return res.end();
    }

    // POST /books/:id/finish -> mark finished
    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const books = loadBooks();
      const book = findBook(books, finishMatch[1]);
      if (!book) {
        res.statusCode = 404;
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.end(notFoundView());
      }
      book.finished = true;
      saveBooks(books);
      res.statusCode = 303;
      res.setHeader('Location', `/books/${book.id}`);
      return res.end();
    }

    // GET /books/:id -> detail (shareable)
    const detailMatch = path.match(/^\/books\/([^/]+)$/);
    if (req.method === 'GET' && detailMatch) {
      const books = loadBooks();
      const book = findBook(books, detailMatch[1]);
      if (!book) {
        res.statusCode = 404;
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.end(notFoundView());
      }
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.end(bookView(book, origin));
    }

    // GET / -> home
    if (req.method === 'GET' && (path === '/' || path === '')) {
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      return res.end(homeView(loadBooks(), origin));
    }

    res.statusCode = 404;
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    return res.end(notFoundView());
  } catch (err) {
    console.error(err);
    res.statusCode = 500;
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    return res.end(page('Error', `<h1>Something went wrong</h1><pre>${escapeHtml(err.message)}</pre>`));
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
  console.log(`Saving to ${DATA_FILE}`);
});

